 const b=await body(req),runId=validRun(b?.runId)?String(b?.runId):'',amendmentHash=str(b?.amendmentHash,64,64),ownerToken=str(b?.ownerToken,16,200),manifest=env.PERSONA_3B_MANIFEST_HASH??PERSONA_3B_MANIFEST_HASH;
